use serde_json::json;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

pub const WORKSPACE_FOLDER: &str = "MidiMarble AI Workspace";
const AGENT_LINE: &str = "Use the MidiMarble MCP tools to inspect and edit MidiMarble projects.\n";

/// Writes the folder a person opens in Claude Code or ChatGPT, pointing at `binary`. Replaces the generated files.
pub fn generate(documents: &Path, binary: &Path) -> io::Result<PathBuf> {
    let folder = documents.join(WORKSPACE_FOLDER);
    fs::create_dir_all(folder.join(".codex"))?;
    let command = binary.display().to_string();
    let mcp = json!({ "mcpServers": { "midimarble": { "args": ["mcp"], "command": command } } });
    fs::write(folder.join(".mcp.json"), format!("{}\n", serde_json::to_string_pretty(&mcp)?))?;
    fs::write(folder.join(".codex/config.toml"), codex_config(&command, &folder))?;
    fs::write(folder.join("README.md"), readme(&command))?;
    fs::write(folder.join("AGENTS.md"), AGENT_LINE)?;
    fs::write(folder.join("CLAUDE.md"), AGENT_LINE)?;
    return Ok(folder);
}

fn codex_config(command: &str, folder: &Path) -> String {
    return format!(
        "# Generated by MidiMarble. Show AI Workspace replaces changes.\n\n[mcp_servers.midimarble]\nargs = [\"mcp\"]\ncommand = {}\ncwd = {}\nstartup_timeout_sec = 10\n",
        toml_string(command),
        toml_string(&folder.display().to_string())
    );
}

fn toml_string(value: &str) -> String {
    return format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""));
}

fn readme(command: &str) -> String {
    return format!(
        "# MidiMarble AI Workspace\n\n\
This folder connects local AI apps to MidiMarble through MCP.\n\n\
MidiMarble must be open with **Help > Enable MCP** on while an AI app uses its tools. Every edit shows live in the window as one named Undo step, so you can step in at any time.\n\n\
## ChatGPT\n\nOpen this folder as a local workspace and trust it when asked. ChatGPT loads the server from `.codex/config.toml`.\n\n\
## Claude\n\nOpen Claude Code in this folder, trust it and approve its project MCP server when asked.\n\n\
## Other AI apps\n\nAdd a local stdio MCP server with this command and the argument `mcp`:\n\n`{}`\n\n\
## Generated files\n\nMidiMarble writes these files. **Show AI Workspace** in the Help menu replaces changes and updates the path if the app moved. For your own setup, copy the folder somewhere else.\n",
        command
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;
    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn writes_every_file_pointing_at_the_binary() {
        let nanos = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
        let documents = std::env::temp_dir().join(format!("mm-workspace-{}", nanos));
        fs::create_dir_all(&documents).unwrap();
        let binary = Path::new("/Applications/Mid \"Marble\".app/Contents/MacOS/MidiMarble - Development");
        let folder = generate(&documents, binary).unwrap();
        assert_eq!(folder, documents.join("MidiMarble AI Workspace"));

        let mcp: Value = serde_json::from_str(&fs::read_to_string(folder.join(".mcp.json")).unwrap()).unwrap();
        assert_eq!(mcp["mcpServers"]["midimarble"]["command"], binary.display().to_string());
        assert_eq!(mcp["mcpServers"]["midimarble"]["args"][0], "mcp");

        let toml = fs::read_to_string(folder.join(".codex/config.toml")).unwrap();
        assert!(toml.contains("[mcp_servers.midimarble]"));
        assert!(toml.contains("Mid \\\"Marble\\\".app"));
        assert!(toml.contains(&format!("cwd = \"{}\"", folder.display())));

        assert_eq!(fs::read_to_string(folder.join("AGENTS.md")).unwrap(), AGENT_LINE);
        assert_eq!(fs::read_to_string(folder.join("CLAUDE.md")).unwrap(), AGENT_LINE);
        assert!(fs::read_to_string(folder.join("README.md")).unwrap().contains("Enable MCP"));

        // Generating again replaces the files, so a moved app gets its new path
        let moved = Path::new("/Applications/MidiMarble.app/Contents/MacOS/MidiMarble");
        generate(&documents, moved).unwrap();
        assert!(fs::read_to_string(folder.join(".mcp.json")).unwrap().contains("MidiMarble.app"));
        fs::remove_dir_all(documents).unwrap();
    }
}
